      vegetable: 'vegetables',
      whole_grain: 'whole_grains',
      refined_grain: 'refined_grains',
      nut: 'nuts',
      seed: 'seeds',
      seed_paste: 'seeds',
      nuts_seeds: 'nuts_seeds',
      fish: 'seafood',
      shellfish: 'seafood',
      seafoods: 'seafood',
      soya: 'soy',
      soybean: 'soy',
      soybeans: 'soy',
      tofu_firm: 'tofu',
      legume: 'legumes',
      legumes: 'legumes',
      legume_veg: 'legumes',
      'legume-veg': 'legumes',
