(function(){
  if (window.__heiActionBridgeInstalled) return; window.__heiActionBridgeInstalled = true;

  function tagMatch(p, tag){
    if (!p) return false;
    const C = window.__HEIClassifiers || {};
    const normalize = C.normalizeTag || (x => String(x || '').toLowerCase().trim());
    const t = normalize(tag);
    if (t === 'dairy') return !!(C.isDairy && C.isDairy(p));
    if (t === 'fruits') return !!(C.isFruit && C.isFruit(p));
    if (t === 'vegetables') return !!((C.isVeg && C.isVeg(p)) || (C.isLegume && C.isLegume(p)));
    if (t === 'whole_grains') return !!(C.isWholeGrain && C.isWholeGrain(p));
    if (t === 'refined_grains') return !!(C.isRefinedGrain && C.isRefinedGrain(p));
    if (t === 'protein_foods') return !!(C.isProteinFood && C.isProteinFood(p));
    if (t === 'seafood_plant_protein') return !!(C.isSeafoodPlantProtein && C.isSeafoodPlantProtein(p));
    if (t === 'nuts_seeds') return !!(C.isNutsSeeds && C.isNutsSeeds(p));
    if (t === 'legumes') return !!(C.isLegume && C.isLegume(p));
    if (t === 'seafood') return !!(C.isSeafood && C.isSeafood(p));
    if (t === 'soy') return !!(C.isSoyProduct && C.isSoyProduct(p));
    if (t === 'animal_protein') return !!(C.isProteinFood && C.isProteinFood(p)) && !(C.isSeafoodPlantProtein && C.isSeafoodPlantProtein(p));
    if (t === 'seafood_plant') return !!(C.isSeafoodPlantProtein && C.isSeafoodPlantProtein(p));
    return !!(C.hasTag ? C.hasTag(p, t) : (Array.isArray(p.tags) && p.tags.map(normalize).includes(t)));
  }

  function pickByTag(tag){
    const DBi = window.DB;
    if (!DBi || !Array.isArray(DBi.items)) return null;
    const list = DBi.items.filter(p => tagMatch(p, tag));
    if (!list.length) return null;
    // prefer lower kcal per 100g for adequacy adds, and higher for moderation adds/reduces? Keep simple: sort by name
    list.sort((a,b)=> String(a.name_ru||'').localeCompare(String(b.name_ru||''), 'ru'));
    return list[0];
  }

  function rationByTag(tag){
    const r = (window.Ration && Array.isArray(window.Ration.current)) ? window.Ration.current : [];
    const DBi = window.DB;
    return r.map(it => ({ it, p: DBi.byKey.get(it.key) })).filter(x => tagMatch(x.p, tag));
  }

  // Add grams by tag (choose a representative item if not in ration)
  window.addEventListener('hei:quick-add', (e)=>{
    try{
      const { tag, grams } = e.detail||{};
      if (!tag || !grams) return;
      const DBi = window.DB, State = window.State || (window.STATE_API||{});
      let target = rationByTag(tag)[0];
      if (target){
        const g = Math.min(5000, (target.it.grams||0) + grams);
        if (State && typeof State.update==='function') State.update(target.it.key, g);
        else {
          const it = window.Ration.current.find(x=>x.key===target.it.key); if (it) it.grams = g;
          window.dispatchEvent(new Event('ration:changed'));
        }
      } else {
        const p = pickByTag(tag); if (!p) return;
        if (State && typeof State.add==='function') State.add(p.key, grams);
        else {
          window.Ration.current.push({ key:p.key, grams });
          window.dispatchEvent(new Event('ration:changed'));
        }
      }
    }catch(_){}
  });

  // Reduce grams by tag
  window.addEventListener('hei:quick-reduce', (e)=>{
    try{
      const { tag, grams } = e.detail||{}; if (!tag || !grams) return;
      const arr = rationByTag(tag).sort((a,b)=> (b.it.grams||0) - (a.it.grams||0));
      let left = grams;
      for (const {it} of arr){
        if (left<=0) break;
        const take = Math.min(it.grams||0, left);
        const g = Math.max(0, (it.grams||0) - take);
        if (window.State && typeof window.State.update==='function') window.State.update(it.key, g);
        else { it.grams = g; window.dispatchEvent(new Event('ration:changed')); }
        left -= take;
      }
    }catch(_){}
  });

  // Swap: reduce from-tag and add to-tag
  window.addEventListener('hei:swap', (e)=>{
    try{
      const d = e.detail||{}; if (!d || !d.from || !d.to) return;
      window.dispatchEvent(new CustomEvent('hei:quick-reduce',{detail:{tag:d.from.tag, grams:+d.from.grams||0}}));
      window.dispatchEvent(new CustomEvent('hei:quick-add',{detail:{tag:d.to.tag, grams:+d.to.grams||0}}));
    }catch(_){}
  });

  // Reduce sodium (mg) by cutting the saltiest items
  window.addEventListener('hei:reduce-sodium', (e)=>{
    try{
      let { mg } = e.detail||{}; mg = +mg||0; if (mg<=0) return;
      const DBi = window.DB;
      const arr = (window.Ration?.current||[]).map(it => ({ it, p: DBi.byKey.get(it.key) }))
        .filter(x => x.p && (x.p.sodium_mg||0)>0)
        .sort((a,b)=> (b.p.sodium_mg||0) - (a.p.sodium_mg||0));
      for (const {it,p} of arr){
        if (mg<=0) break;
        const mgPerGram = (p.sodium_mg||0)/100;
        if (mgPerGram<=0) continue;
        const gramsToCut = Math.min(it.grams||0, Math.ceil(mg / mgPerGram));
        const g = Math.max(0, (it.grams||0) - gramsToCut);
        if (window.State && typeof window.State.update==='function') window.State.update(it.key, g);
        else { it.grams = g; window.dispatchEvent(new Event('ration:changed')); }
        mg -= gramsToCut * mgPerGram;
      }
    }catch(_){}
  });
})();

