(function(){
  function getTotalsSectionNode() {
    var sec = document.getElementById('totalsSection');
    if (!sec) return null;
    var clone = sec.cloneNode(true);
    var tb = clone.querySelector('#totalsActions');
    if (tb) tb.remove();
    var nameEl = document.getElementById('needs_person_name');
    if (nameEl && nameEl.value.trim()) {
      var nameDiv = document.createElement('div');
      nameDiv.style.fontWeight = '600';
      nameDiv.style.marginBottom = '4px';
      nameDiv.textContent = 'Пациент: ' + nameEl.value.trim();
      clone.insertBefore(nameDiv, clone.firstChild);
    }
    var dtDiv = document.createElement('div');
    dtDiv.style.fontSize = '12px';
    dtDiv.style.marginBottom = '8px';
    dtDiv.textContent = 'Дата и время: ' + (new Date()).toLocaleString();
    clone.insertBefore(dtDiv, clone.firstChild.nextSibling);
    return clone;
  }
  function openPrintWindowWithTotals() {
    var clone = getTotalsSectionNode();
    if (!clone) { window.print(); return; }
    var headHtml = document.head ? document.head.innerHTML : '';
    var w = window.open('', '_blank');
    if (!w) { alert('Разрешите всплывающие окна для печати.'); return; }
    var docHtml = '<!doctype html><html><head>' + headHtml +
      '<style>@media print{*{-webkit-print-color-adjust:exact !important;print-color-adjust:exact !important;}@page{margin:14mm;}}</style>' +
      '<meta charset="utf-8"><title>Итоги и дневные нормы</title></head><body style="margin:0; padding:0;">' +
      clone.outerHTML + '</body></html>';
    w.document.open();
    w.document.write(docHtml);
    w.document.close();
    try { w.focus(); w.print(); } catch(e) { console.warn(e); }
  }
  function saveTotalsAsPdf() {
    var clone = getTotalsSectionNode();
    if (!clone) { alert('Секция итогов не найдена'); return; }
    if (typeof html2pdf === 'undefined') {
      (window.__nutritionPdfUnavailable || function(){ alert('Экспорт в PDF сейчас недоступен: библиотека экспорта не загрузилась. Используйте печать страницы или попробуйте позже.'); })();
      return;
    }
    var wrapper = document.createElement('div');
    wrapper.style.padding = '12px';
    wrapper.appendChild(clone);
    var opt = {
      margin: 10,
      filename: 'totals_' + new Date().toISOString().slice(0,19).replace(/[:T]/g,'-') + '.pdf',
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };
    html2pdf().set(opt).from(wrapper).save();
  }
  function init() {
    var btnPrint = document.getElementById('printTotalsBtn');
    var btnPdf   = document.getElementById('exportTotalsPdfBtn');
    if (btnPrint) btnPrint.addEventListener('click', openPrintWindowWithTotals);
    if (btnPdf)   btnPdf.addEventListener('click', saveTotalsAsPdf);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

