  html += '.print-block>h2 small,.print-block>h2 span{font-size:0.9em;text-transform:none;}';
  // сетка итогов
  html += '.totals-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}';
