  html += '.bar{height:100%;background:var(--primary);}';
  html += '.bar.warn{background:var(--warn);}';
  html += '.bar.danger{background:var(--danger);}';
  html += '.page-footer{position:fixed;bottom:6mm;right:10mm;font-size:10px;color:#666;}';
  html += '</style>';
  html += '</head><body style="margin:0;padding:12px 16px;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;">';
  html += '<h1 style="margin-top:0;">Сводный отчёт по нутритивным расчётам</h1>';
