    if (/mayonnaise|майонез/.test(text)) out.push('Заправка такая же: майонез, сметана, йогурт или масло?');
    if (/fried|chips|чипс|жар/.test(text)) out.push('Есть ли жареный картофель, чипсы или масло от жарки?');
    if (/kefir|квас|kvass|кефир/.test(text)) out.push('Основа совпадает: квас/кефир/сметана?');
