    if (unitType === 'зубчик') return m === 1 ? 'зубчик' : (m >= 2 && m <= 4 ? 'зубчика' : 'зубчиков');
    if (unitType === 'початок') return m === 1 ? 'початок' : (m >= 2 && m <= 4 ? 'початка' : 'початков');
