      if (units.some(function(u){ return String(u.unit_type || '').indexOf('/') >= 0; })) return disable('disabled_ambiguous_unit','ambiguous unit_type');
      if (units.every(function(u){ return String(u.confidence || '') === 'low'; })) return disable('disabled_low_confidence','low confidence');
      if (units.some(function(u){ return String(u.priority || '') === 'P1'; })) return disable('disabled_medium_review','priority P1 requires manual review');
