    var rows=Object.keys(labels).map(function(k){ var v=Number(p.domains[k]); return '<tr><td>'+esc(labels[k])+'</td><td>'+fmt(v,1)+'/100</td><td>'+(v<70?'требует коррекции':(v<85?'рабочая зона':'сильная сторона'))+'</td></tr>'; });
