      if (!target) return fmt(grams,0)+' мл';
      if (grams < target*0.35) return 'мало: '+fmt(grams,0)+' / '+fmt(target,0)+' мл';
      if (grams < target*0.75) return 'частично: '+fmt(grams,0)+' / '+fmt(target,0)+' мл';
      return 'близко к ориентиру: '+fmt(grams,0)+' / '+fmt(target,0)+' мл';
