      '<section><h4>Добавить в рацион</h4>'+addHtml+'</section>' +
      '<section><h4>Сократить в рационе</h4><p class="hpapply-micro">Сектор: '+esc(SECTOR_LABEL[red.sector] || red.sector || '—')+'</p>'+redHtml+'</section>' +
    '</div>';
