  function reportAmount(value,unit){var u=clean(unit),digits=/мг|мкг|ккал/i.test(u)?0:1;return fmt(value,digits)+(u?' '+u:'');}
  function guardrailsModel(base,vm){if(vm&&vm.hei&&Array.isArray(vm.hei.guardrails))return clone(vm.hei.guardrails)||[];var a=base&&base.dietAssessment||{},out=[];arr(a.upperLimitFlags).forEach(function(f){out.push({code:'critical',title:clean(f.title)||'Превышение применимого верхнего уровня',body:reportAmount(f.value,f.unit)+' при верхнем уровне '+reportAmount(f.threshold,f.unit)+'.',nutrient:clean(f.nutrient)});});arr(a.guidelineFlags).forEach(function(f){out.push({code:'high',title:clean(f.title)||'Показатель выше ориентира',body:reportAmount(f.value,f.unit)+' при ориентире '+reportAmount(f.threshold,f.unit)+'.',nutrient:clean(f.nutrient)});});arr(a.limitations||a.notEvaluable).forEach(function(f){out.push({code:'unavailable',title:clean(f&&f.title)||'Показатель не оценён',body:clean(f&&f.message)||'Данных недостаточно; отсутствие оценки не считается нулевым значением.',nutrient:clean(f&&f.nutrient)});});return out;}
  function heiModel(base,vm){var model=vm&&vm.hei&&vm.hei.model||base&&base.hei||{},rows=vm&&vm.hei&&arr(vm.hei.rows);if(!rows||!rows.length)rows=arr(base&&base.hei&&base.hei.rows).map(function(x){return {key:x.key,title:x.title||x.label||x.key,points:num(x.points),maxPoints:num(x.maxPoints,10),pct:num(x.maxPoints)?num(x.points)/num(x.maxPoints)*100:0,actual:x.value||'',norm:x.norm||'',status:{code:'',label:''},confidence:'',contributors:{positive:{items:[]}}};});return {available:isFinite(Number(model.total)),total:num(model.total,NaN),grade:model.grade||'',summary:clean(base&&base.hei&&base.hei.summary),rows:arr(rows).map(function(x){return {key:x.key,title:clean(x.title),points:num(x.points),maxPoints:num(x.maxPoints,10),pct:num(x.pct),actual:humanizeHeiMeasure(x.actual),norm:humanizeHeiMeasure(x.norm),status:{code:x.status&&x.status.code||'',label:clean(x.status&&x.status.label)},confidence:clean(x.confidence),contributors:topContributors(x)};}),guardrails:guardrailsModel(base,vm)};}
  function assessmentModel(base){var c=base&&base.patientContent||{};return {conclusion:clean(c.conclusion),strengths:arr(c.strengths).slice(0,3).map(function(x){return {title:clean(x.title),detail:clean(x.detail||x.reason),action:clean(x.action)};}),priorities:arr(c.priorities).slice(0,5).map(function(x){return {title:clean(x.title),reason:clean(x.reason),action:clean(x.action),kind:clean(x.kind)};}),firstAction:clone(c.firstAction)||null};}
  function qualityModel(base,vm){var p=base&&base.provenanceQuality||{},s=p.summary||{},source=vm&&vm.sourceQuality||base&&base.sourceQuality||{};return {label:clean(source.label)||clean(sourceQualityLabel(source))||'не определено',high:num(s.high||source.high),medium:num(s.medium||source.medium),low:num(s.low||source.low),total:num(s.total||source.total),assumedZero:num(s.assumed_zero_products),limitations:arr(base&&base.dietAssessment&&(base.dietAssessment.limitations||base.dietAssessment.notEvaluable)).map(function(x){return clean(x&&x.message||x&&x.title||x);}).filter(Boolean)};}
  function sourceQualityLabel(x){var label=clean(x&&x.label);if(label)return label;var tier=String(x&&x.tier||'').toUpperCase();return tier==='HIGH'?'высокая':tier==='MEDIUM'?'средняя':tier==='LOW'?'ограниченная':'';}
  function snapshotHash(base,options){return String(base&&base.hash||'')+'::'+JSON.stringify(options||{});} 

  function buildReportModel(options){options=options||getStoredOptions();var api=reportApi(),base=api&&api.buildReportModel?api.buildReportModel({force:true}):null;if(!base)throw new Error('Единый расчётный снимок отчёта недоступен.');var vm=null;try{vm=analysisApi()&&analysisApi().getViewModel?analysisApi().getViewModel():null;}catch(_){}
    var status=base.productCorrection&&base.productCorrection.analysisState||((base.rationPositionCount||0)>0?'complete':'empty'),profile=profileModel(base);var model={schemaVersion:SCHEMA,version:VERSION,generatedAt:new Date().toISOString(),generatedOn:base.generatedAt||new Date().toLocaleDateString('ru-RU'),status:status,profile:profile,needs:needsModel(base),ration:rationModel(base),totals:clone(base.totals)||{},nutrients:nutrientModel(base,vm),hei:heiModel(base,vm),assessment:assessmentModel(base),dataQuality:qualityModel(base,vm),appliedChanges:appliedChanges(),reportOptions:clone(options),metadata:{sourceReportVersion:base.version||'',sourceHash:base.hash||'',calculationSource:base.calculationSource||'NutritionCalculationCore',normSystem:profile.normRegion,externalValidationClaimAllowed:false}};model.hash=snapshotHash(base,options);lastModel=deepFreeze(model);lastHash=model.hash;lastOptions=clone(options);return lastModel;}

  function kv(label,value){return '<div class="workspace-report-kv"><span>'+esc(label)+'</span><strong>'+esc(value==null||value===''?'—':value)+'</strong></div>';}
  function statusPill(label,code){return '<span class="workspace-report-status is-'+esc(normalizeStatus({code:code}))+'">'+esc(label||'Без статуса')+'</span>';}
  function section(title,kicker,body,meta,cls){return '<section class="workspace-report-section '+(cls||'')+'"><div class="workspace-report-section__head"><div><span>'+esc(kicker||'Раздел отчёта')+'</span><h3>'+esc(title)+'</h3></div>'+(meta?'<small>'+esc(meta)+'</small>':'')+'</div>'+body+'</section>';}
  function contributorsText(items){items=arr(items);if(!items.length)return '';return '<div class="workspace-report-contributors">Основные вкладчики: '+items.map(function(x){return esc(x.name)+(x.share?(' · '+fmt(x.share,0)+'%'):'');}).join('; ')+'</div>';}
  function coverHtml(m){var complete=m.status==='complete';return '<section class="workspace-report-section workspace-report-cover"><span class="workspace-report-status '+(complete?'is-ok':'is-attention')+'">'+(complete?'Текущий рацион':'Предварительный отчёт')+'</span><h2>Отчёт по рациону: '+esc(m.profile.name)+'</h2><p>'+esc(complete?'Потребности, рацион и результаты анализа собраны из одного расчётного снимка.':'Рацион заполнен не полностью. Итоги отражают только введённые продукты.')+'</p><div class="workspace-report-kv-grid">'+kv('Дата',m.generatedOn)+kv('Цель',m.profile.goal)+kv('Система норм',m.profile.normRegion)+kv('Позиций в рационе',String(m.ration.count))+kv('Энергия',fmt(m.totals.kcal,0)+' ккал')+kv('HEI',m.hei.available?fmt(m.hei.total,0)+'/100'+(m.hei.grade?' · '+m.hei.grade:''):'не рассчитан')+kv('Расчёт потребностей',m.needs.inputComplete?'выполнен':'не завершён')+kv('Статус данных',m.dataQuality.label)+'</div></section>';}
  function profileHtml(m){var p=m.profile,n=m.needs;return section('Человек и расчётные потребности','Основание отчёта','<div class="workspace-report-kv-grid">'+kv('Имя',p.name)+kv('Пол',p.sex)+kv('Возраст',p.age)+kv('Рост',p.height)+kv('Масса тела',p.weight)+kv('Активность',p.activity)+kv('Энергия',n.energy==='—'?'не рассчитана':n.energy+' ккал/сут')+kv('Белок',n.protein==='—'?'не рассчитан':n.protein+' г/сут')+kv('Жиры',n.fat==='—'?'не рассчитаны':n.fat+' г/сут')+kv('Углеводы',n.carbs==='—'?'не рассчитаны':n.carbs+' г/сут')+kv('Жидкость',n.fluid==='—'?'не рассчитана':n.fluid+' мл/сут')+kv('Метод',n.method)+'</div>','Профиль: '+p.state);}
  function rationRowsHtml(m){if(!m.ration.items.length)return '<div class="workspace-report-empty"><strong>Рацион пока пуст</strong><p>Добавьте продукты, чтобы сформировать содержательный отчёт.</p></div>';var body=m.ration.items.map(function(x){return '<tr><td>'+esc(x.name)+(x.level?'<small>ингредиент составного блюда</small>':'')+'</td><td>'+fmt(x.grams,1)+' г</td><td>'+esc(x.note||'—')+'</td></tr>';}).join('');var mobile=m.ration.items.map(function(x){return '<article class="workspace-report-mobile-row"><div class="workspace-report-mobile-row__top"><strong>'+esc(x.name)+'</strong><b>'+fmt(x.grams,1)+' г</b></div>'+(x.note?'<p>'+esc(x.note)+'</p>':'')+'</article>';}).join('');return '<div class="workspace-report-table-wrap"><table class="workspace-report-table"><thead><tr><th>Продукт и состав</th><th>Количество</th><th>Примечание</th></tr></thead><tbody>'+body+'</tbody></table></div><div class="workspace-report-mobile-list">'+mobile+'</div>';}
  function assessmentHtml(m){var a=m.assessment,priorities=a.priorities.map(function(x,i){return '<article class="workspace-report-card"><span>Направление '+(i+1)+'</span><strong>'+esc(x.title)+'</strong><p>'+esc(x.reason)+'</p>'+(x.action?'<em>'+esc(x.action)+'</em>':'')+'</article>';}).join(''),strengths=a.strengths.map(function(x){return '<article class="workspace-report-card"><span>Сильная сторона</span><strong>'+esc(x.title)+'</strong><p>'+esc(x.detail)+'</p></article>';}).join('');return section('Краткий итог','Главные выводы','<p class="workspace-report-lead">'+esc(a.conclusion||'Вывод будет сформирован после расчёта полного рациона.')+'</p>'+(priorities?'<div class="workspace-report-priorities">'+priorities+'</div>':'')+(strengths?'<h4>Что уже выглядит устойчиво</h4><div class="workspace-report-strengths">'+strengths+'</div>':''),'Не более пяти приоритетов');}
  function macroHtml(m){return '<div class="workspace-report-kv-grid">'+kv('Энергия',fmt(m.totals.kcal,0)+' ккал')+kv('Белки',fmt(m.totals.protein_g,1)+' г')+kv('Жиры',fmt(m.totals.fat_g,1)+' г')+kv('Углеводы',fmt(m.totals.carbs_g,1)+' г')+kv('Клетчатка',fmt(m.totals.fiber_g,1)+' г')+kv('Насыщенные жиры',fmt(m.totals.sfa_g,1)+' г')+kv('Соль',fmt(m.totals.salt_g,1)+' г')+kv('Натрий',fmt(m.totals.sodium_mg,0)+' мг')+'</div>';}
  function nutrientRows(m){return [].concat(m.nutrients.basic,m.nutrients.limits,m.nutrients.vitamins,m.nutrients.minerals,m.nutrients.other);}
  function nutrientDetailHtml(m){var rows=nutrientRows(m);if(!rows.length)return '<p>Подробные значения пока недоступны.</p>';var body=rows.map(function(x){return '<tr><td>'+esc(x.title)+contributorsText(m.reportOptions.contributors?x.contributors:[])+'</td><td>'+fmt(x.actual,x.actual<10?2:1)+' '+esc(x.unit)+'</td><td>'+(x.target?fmt(x.target,x.target<10?2:1)+' '+esc(x.unit):'—')+'</td><td>'+statusPill(x.status.label,x.status.code)+'</td><td>'+esc(x.quality||'—')+'</td></tr>';}).join('');var mobile=rows.map(function(x){return '<article class="workspace-report-mobile-row"><div class="workspace-report-mobile-row__top"><strong>'+esc(x.title)+'</strong>'+statusPill(x.status.label,x.status.code)+'</div><dl><div><dt>Факт</dt><dd>'+fmt(x.actual,x.actual<10?2:1)+' '+esc(x.unit)+'</dd></div><div><dt>Ориентир</dt><dd>'+(x.target?fmt(x.target,x.target<10?2:1)+' '+esc(x.unit):'—')+'</dd></div></dl>'+contributorsText(m.reportOptions.contributors?x.contributors:[])+'</article>';}).join('');return '<div class="workspace-report-table-wrap"><table class="workspace-report-table"><thead><tr><th>Показатель</th><th>Факт</th><th>Ориентир</th><th>Статус</th><th>Достоверность</th></tr></thead><tbody>'+body+'</tbody></table></div><div class="workspace-report-mobile-list">'+mobile+'</div>';}
  function guardrailsHtml(m){var rows=arr(m.hei.guardrails);if(!rows.length)return '<div class="workspace-report-card"><span>Отдельные ограничения</span><strong>Подтверждённых превышений применимых верхних уровней не найдено</strong><p>Общий балл HEI всё равно следует рассматривать вместе с отдельными компонентами и качеством данных.</p></div>';return '<div class="workspace-report-guardrails">'+rows.map(function(x){return '<article class="workspace-report-card is-'+esc(normalizeStatus({code:x.code}))+'"><span>Отдельное ограничение</span><strong>'+esc(x.title||'Показатель требует внимания')+'</strong><p>'+esc(x.body||'Проверьте значение и применимый ориентир.')+'</p></article>';}).join('')+'</div>';}
  function heiHtml(m){if(!m.hei.available)return section('HEI-2020','Структура рациона','<div class="workspace-report-empty"><strong>HEI пока не рассчитан</strong><p>Индекс появится после расчёта рациона.</p></div>');var intro='<div class="workspace-report-kv-grid">'+kv('Итоговый HEI',fmt(m.hei.total,0)+'/100')+kv('Категория',m.hei.grade||'—')+kv('Компонентов',String(m.hei.rows.length))+kv('Отдельных ограничений',String(m.hei.guardrails.length))+'</div>';
    intro+='<h4>Отдельные ограничения</h4>'+guardrailsHtml(m);if(!m.reportOptions.fullHei)return section('HEI-2020','Структура рациона',intro,'Краткий итог');var body=m.hei.rows.map(function(x){return '<tr><td>'+esc(x.title)+contributorsText(m.reportOptions.contributors?x.contributors:[])+'</td><td>'+fmt(x.points,1)+' из '+fmt(x.maxPoints,0)+'</td><td>'+esc(x.actual||'—')+'</td><td>'+esc(x.norm||'—')+'</td><td>'+statusPill(x.status.label,x.status.code)+'</td></tr>';}).join('');var mobile=m.hei.rows.map(function(x){return '<article class="workspace-report-mobile-row"><div class="workspace-report-mobile-row__top"><strong>'+esc(x.title)+'</strong><b>'+fmt(x.points,1)+'/'+fmt(x.maxPoints,0)+'</b></div><dl><div><dt>Факт</dt><dd>'+esc(x.actual||'—')+'</dd></div><div><dt>Ориентир</dt><dd>'+esc(x.norm||'—')+'</dd></div></dl>'+contributorsText(m.reportOptions.contributors?x.contributors:[])+'</article>';}).join('');return section('HEI-2020','Структура рациона',intro+'<div class="workspace-report-table-wrap"><table class="workspace-report-table"><thead><tr><th>Компонент</th><th>Балл</th><th>Факт</th><th>Ориентир</th><th>Статус</th></tr></thead><tbody>'+body+'</tbody></table></div><div class="workspace-report-mobile-list">'+mobile+'</div>','Полный разбор компонентов');}
  function changesHtml(m){if(!m.reportOptions.appliedChanges||!m.appliedChanges.length)return '';var cards=m.appliedChanges.map(function(x){var detail=x.type==='replacement'?(x.product+' '+fmt(x.before,0)+' '+x.unit+' → '+x.replacement+' '+fmt(x.after,0)+' '+x.unit):(x.product+' · '+(x.before!=null?fmt(x.before,0)+' → ':'')+fmt(x.after,0)+' '+x.unit);return '<article class="workspace-report-card"><span>'+esc(x.title)+'</span><strong>'+esc(detail)+'</strong><p>Отчёт отражает рацион после применения этого изменения.</p></article>';}).join('');return section('Применённые изменения','Текущий сеанс','<div class="workspace-report-changes">'+cards+'</div>','Только подтверждённые действия');}
  function qualityHtml(m){var q=m.dataQuality;return section('Качество исходных данных','Достоверность','<div class="workspace-report-quality"><div class="workspace-report-card"><span>Общая оценка</span><strong>'+esc(q.label)+'</strong><p>Высокая: '+q.high+' · средняя: '+q.medium+' · ограниченная: '+q.low+'.</p></div><div class="workspace-report-card"><span>Ограничения</span><strong>'+(q.limitations.length?q.limitations.length:'не отмечены')+'</strong><p>'+(q.limitations.length?esc(q.limitations.slice(0,3).join(' ')):'Отсутствующие значения не подменяются доказанным нулём.')+'</p></div></div>'+(q.assumedZero?'<p class="workspace-report-note">В '+q.assumedZero+' карточках встречаются условные нули: это означает отсутствие надёжного значения, а не отсутствие нутриента.</p>':''));}
  function methodologyHtml(m){if(!m.reportOptions.methodology)return '';return section('Методика и границы применения','Дополнительные сведения','<p>Расчётные значения сформированы единым расчётным контуром. Экран отчёта, печать и PDF используют один сериализуемый снимок данных и одинаковые формулировки.</p><p>Инструмент предназначен для ориентировочного анализа рациона. Он не выполняет клиническую диагностику и не заменяет решение врача или другого профильного специалиста.</p><p class="workspace-report-note">Версия расчётного снимка: '+esc(m.metadata.sourceReportVersion)+' · источник: '+esc(m.metadata.calculationSource)+'.</p>');}
  function buildBodyHtml(m){var html=coverHtml(m)+profileHtml(m)+section('Состав рациона','Фактический ввод',rationRowsHtml(m),m.ration.count+' позиций')+assessmentHtml(m)+section('Энергия и основные показатели','Краткая сводка',macroHtml(m));if(m.reportOptions.detailedNutrients)html+=section('Нутриенты и ориентиры','Подробный анализ',nutrientDetailHtml(m),nutrientRows(m).length+' показателей');html+=heiHtml(m)+qualityHtml(m)+changesHtml(m)+methodologyHtml(m);return '<article class="workspace-report-document" data-report-schema="'+esc(SCHEMA)+'" data-report-version="'+esc(VERSION)+'">'+html+'</article>';}
  function documentStyles(){return '<style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{margin:0;color:#172033;background:#fff;font:11pt/1.45 Arial,sans-serif}.workspace-report-document{display:grid;gap:10px}.workspace-report-section{border:1px solid #cbd5e1;border-radius:10px;padding:12px;break-inside:auto}.workspace-report-section__head{display:flex;justify-content:space-between;gap:10px;margin-bottom:8px}.workspace-report-section__head span,.workspace-report-card>span{display:block;color:#64748b;font-size:8.5pt;font-weight:700;text-transform:uppercase}.workspace-report-section__head h3{margin:2px 0 0}.workspace-report-cover{background:#f7fbff}.workspace-report-cover h2{margin:5px 0}.workspace-report-cover p,.workspace-report-card p{color:#475569}.workspace-report-kv-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:8px}.workspace-report-kv,.workspace-report-card{border:1px solid #dbe4ee;border-radius:7px;padding:7px;break-inside:avoid}.workspace-report-kv span{display:block;color:#64748b;font-size:8.5pt}.workspace-report-kv strong{display:block}.workspace-report-priorities,.workspace-report-strengths,.workspace-report-changes{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.workspace-report-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:9pt}.workspace-report-table th,.workspace-report-table td{padding:5px;border:1px solid #dbe4ee;text-align:left;vertical-align:top;overflow-wrap:anywhere}.workspace-report-table th{background:#f8fafc}.workspace-report-table thead{display:table-header-group}.workspace-report-table small,.workspace-report-contributors{display:block;color:#64748b;font-size:8pt}.workspace-report-mobile-list{display:none}.workspace-report-status{display:inline-block;border-radius:999px;padding:2px 6px;background:#eef6ff;font-size:8pt;font-weight:700}.workspace-report-quality{display:grid;grid-template-columns:1fr 1fr;gap:6px}.workspace-report-note{padding:7px;border-left:3px solid #94a3b8;background:#f8fafc;color:#475569}@media print{.workspace-report-section{box-shadow:none}.workspace-report-cover{break-after:avoid}.workspace-report-table tr{break-inside:avoid;page-break-inside:avoid}}</style>';}
  function buildDocumentHtml(model){var m=model||buildReportModel(getStoredOptions());return '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Отчёт по рациону — '+esc(m.profile.name)+'</title>'+documentStyles()+'</head><body>'+buildBodyHtml(m)+'</body></html>';}
  function openWindow(kind){var win=w.open('','_blank','width=1040,height=900,scrollbars=yes,resizable=yes');if(!win){w.alert('Браузер заблокировал окно отчёта. Разрешите всплывающие окна и повторите действие.');return null;}try{win.document.open();win.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Подготовка отчёта</title></head><body style="font:16px/1.5 Arial;padding:30px">Подготавливаем отчёт…</body></html>');win.document.close();}catch(_){}return win;}
  function print(kind){var win=openWindow(kind||'print');if(!win)return false;w.setTimeout(function(){try{var model=buildReportModel(getStoredOptions()),html=buildDocumentHtml(model);win.document.open();win.document.write(html);win.document.close();win.focus();win.setTimeout(function(){try{win.print();}catch(_){}},180);}catch(error){try{win.document.body.innerHTML='<h1>Не удалось собрать отчёт</h1><pre>'+esc(error&&error.message||error)+'</pre>';}catch(_){}}},10);return true;}
